"""Finish the current multimedia follow-ups before returning to the remaining prose."""
from copy import deepcopy
from best_guess_helpers import current_data,change,write_revision,dated_source,guessed_record,retained_decision,DATE
D=current_data();changes=[];records=[]
sources=[
 dated_source('src-karrakin-official-socialdivision','The Karrakin Trade Baronies','Massif Press','https://massif-press.itch.io/field-guide-the-karrakin-trade-baronies?click_to_load=true','Official description: major Union member with immense industry, strong social division, titled nobles resisting equality and industrial/political strain.','A broad setting premise, not every resident being a serf or a uniform local necessities policy.',kind='publisher_description',access='Official setting-description paragraphs read'),
 dated_source('src-starsector-church-industry','Luddic Church: pastoral ideal and actual industry','Starsector Wiki contributors','https://starsector.fandom.com/wiki/Luddic_Church','Faction description and reference: pastoral ideal and distrust of technology coexist with agricultural, domestic-goods and polluted industrial worlds; the Church differs from the more extreme Path.','Fan reference reproducing faction context, not proof of a universal total machine ban or one welfare law.',access='Indexed faction ideal, industrial worlds and Path distinction read'),
 dated_source('src-starsector-tritach-technical','Tri-Tachyon: corporate technology','Starsector Wiki contributors','https://starsector.wiki.gg/wiki/Tri-Tachyon','Overview describes a megacorporation specializing in AI and high-power devices, with an industrial colony at Culann.','Speculative AI-mastermind material is not used as established controller identity; no household census.',access='Indexed corporate specialization and industrial-colony overview read'),
 dated_source('src-suffadv-patent-primary','Sufficiently Advanced: Patent Office and material replication','Colin Fredericks','https://d1vzi28wh99zvq.cloudfront.net/pdf_previews/51719-sample.pdf','Sample page 2: replicators and transmutation, intellectual-property economy, working inspectors and Transcendental AI employers behind the Patent Office.','Bounded official sample, not all fourteen civilizations sharing one household constitution; agent support remains a narrow work-unit interpretation.',kind='primary_text',access='Official sample’s Patent Office page read'),
]
for s in sources:changes.append(change(D,'sources',s))
def add(cid,rid,name,work,media,period,pop,excluded,desc,values,bounds,bases,facts,assumptions,qualification,regime=3,zero=True,proxy=False,extra=None,branch=None,continuity=None):
 refs=D['decisions'][cid]['source_ids']+(extra or [])
 r=guessed_record(cid,rid,name,work,name,media,continuity or 'Named setting, medium and stated period only',period,pop,excluded,desc,values,bounds,bases,refs,regime,facts,assumptions,qualification,zero=zero,proxy=proxy,branch=branch)
 records.append(r);return r

add('c0872','ths-us-fifthwave-market','Transhuman Space (the Fifth Wave United States)','Transhuman Space',['tabletop'],'The functioning Fifth Wave US technical economy','Living biological human US residents','European support rules and TSA information policy are not imported; robot labor is separately disclosed.',
'''The setting combines fusion power, helper robots and differing national economic systems. This point selects the Fifth Wave United States as a distinct human access population, rather than copying the European floor or TSA information policy. The guarantee best guess is mixed and conditional, with market dependence an explicit editorial interpretation of the local institutions. Technical capacity alone does not establish free necessities for every household.

 Human commercial and civic agency receives moderate positive control weight, qualified by concentrated wealth and practical infrastructure dependencies. Helper robots are not automatically sovereign providers. The moderate nonworking scenario counts services, research, administration, repair, care and useful creation. Robot numbers and national prosperity are not converted into an all-age participation statistic. The partial-transition admission remains low confidence because the short source does not detail household coverage. Its broad bounds preserve meaningful institutional differences without inventing a canonical uniform welfare law or treating every Fifth Wave country as the same society.''',
(.3,.55,.4),([-.75,.95],[0,1],[.05,.9]),('Mixed market/civic access is the explicit US household scenario.','Human commercial and civic agency is central with concentration possible.','Useful services and care remain; helper robots and prosperity are not participation.'),
['The setting has fusion power, helper robots, variable prosperity and different national systems.'],['US market-dependent material access is an editorial local model.','European and TSA institutions are not copied into this access population.'],'Retain the distinct national automation-transition comparison with the local policy estimate labeled.',regime=4,zero=False)

add('c0874','lancer-armory-purview-zero','Lancer (Harrison Armory’s Purview)','Lancer',['tabletop'],'The functioning corpro-state Purview','Living human Purview residents, including people without full citizenship','Union Core Pillars are not assumed implemented identically; military service and production remain work.',
'''Purview citizenship is conditional, service can earn status, and Harrison Armory manufactures advanced weapons and other goods. The guarantee best guess is weak across residents because high productive capacity does not grant everyone the Core’s secure necessities floor. This zero variant treats fabrication and retained service as a concrete comparison, without assuming that ordinary goods are either universally free or entirely manually produced.

 Concentrated human corpro-state authority receives control near the elite reference point. Advanced automated armaments do not automatically mean an AI owns the whole sustaining economy. The low nonworking scenario counts manufacturing, military duties, administration, maintenance, care and useful creation. Citizenship and enlistment are not a population employment statistic, and excluded residents’ informal contributions still count. The scope is the functioning Purview rather than every world under Union’s aspirations. Broad intervals preserve varied local implementation while retaining the familiar corporate alternative to the already-scoped Third Committee Core.''',
(.65,.03,.25),([-.5,.98],[0,.4],[.02,.85]),('Conditional citizenship and service limit an assumed common floor.','Human corpro-state concentration is central.','Production, service and care remain work; citizenship is not participation.'),
['Purview citizenship is conditional, service can earn status and the corpro-state manufactures advanced goods.'],['Ordinary material coverage and automation depth are low-confidence estimates.','Union Core implementation is not extended to the Purview.'],'Retain the distinct corporate citizenship/production model with exclusion visible.')

add('c0875','lancer-karrakin-industrial-zero','Lancer (the Karrakin Trade Baronies)','Lancer',['tabletop'],'The functioning industrial Baronies amid political strain','Living human Baronies residents across social strata','Not every resident is a serf; Union membership does not automatically implement Core equality everywhere.',
'''The official setting describes vast industry and deep social division, with titled nobles resisting Union’s promised equality. Industrial and political strain qualify any simple image of universal abundance. The guarantee best guess is weak across residents despite substantial material capacity. This zero variant interprets automated industry alongside continuing useful roles, without assigning identical serf status or equal free necessities to every person in every barony.

 Human nobles and powerful institutions receive concentrated control weight, with some wider productive agency left inside the interval. A Union affiliation does not by itself establish shared resident ownership. The low nonworking scenario counts production, administration, services, maintenance, care and useful creation. Wealth, noble titles and political ideology are not labor statistics. The point covers a broad functioning institutional model with local variation explicit, rather than inventing one precise household statute. It remains distinct from the Third Committee Core and Harrison Armory’s corpro-state access conditions.''',
(.7,.05,.25),([-.45,.98],[0,.5],[.02,.85]),('Deep social division and resistance to equality weaken common material security.','Titled human nobles and institutions concentrate productive authority.','Industrial and caring roles continue; title or serf status is not a work census.'),
['Official setting material describes immense industry, titled noble power, social division and political/economic strain.'],['Ordinary industrial automation and household coverage are estimated.','Not all residents are assigned one legal or work status.'],'Retain the famous stratified industrial Union member with local variation and real work explicit.',extra=['src-karrakin-official-socialdivision'])

add('c0880','starsector-luddic-industry-zero','Starsector (the Luddic Church economy)','Starsector',['game'],'The functioning Church worlds with pastoral ideals and actual industry','Living biological human Church-world residents','The more extreme Luddic Path is separate; distrust of technology is not a total ban on every machine.',
'''The Church promotes a pastoral ideal and distrust of technology while its worlds still produce agriculture, domestic goods and heavily polluting industry. It is therefore a selective-restraint comparison rather than a civilization with no machinery. The guarantee best guess is mixed and conditional because fertile worlds and industrial output do not specify equal secure necessities. The source does not support treating every Church community as uniformly poor or fully automated.

 Human religious and local institutions receive positive control weight, qualified by concentrated leadership. Industrial systems are not automatically an autonomous AI sovereign. The low nonworking scenario counts agriculture, manufacture, services, administration, maintenance, care and useful creation. Pastoral ideals are not a labor percentage, and actual industrial work remains useful despite religious rhetoric. The scope excludes the more extreme Path’s different methods. This zero variant retains a recognizable technology-restraint economy with its real material production visible, rather than importing one ship’s limitations as a universal machine ban.''',
(.35,.25,.25),([-.7,.95],[0,.8],[.02,.85]),('Productive worlds permit a floor but universal household access is uncertain.','Human religious/local authority retains agency with concentration possible.','Agriculture, industry and care remain; pastoral ideals are not participation.'),
['The Church’s pastoral ideal coexists with agricultural, domestic-goods and polluted industrial worlds.','It differs from the more extreme Luddic Path.'],['The common material floor and exact technological restraint vary locally.','A total machine ban is not asserted.'],'Retain the selective-restraint economy with industry and faction distinctions verified.',extra=['src-starsector-church-industry'])

add('c0881','starsector-tritach-corporate-zero','Starsector (Tri-Tachyon’s corporate economy)','Starsector',['game'],'The functioning corporate industrial colonies','Living biological human Tri-Tachyon residents','AI operations are disclosed, but speculative mastermind claims are not established sovereign identity; crew hiring remains work.',
'''Tri-Tachyon specializes in advanced AI and high-power devices and has industrial colonies. That is real technical productive capacity, while ordinary human access remains tied to an uncertain corporate order. The guarantee best guess is weak because capability and corporate wealth do not become a dependable equal necessities floor. This zero variant keeps continuing human roles visible rather than assuming advanced AI has already removed all useful biological contribution.

 Corporate authority receives control near concentrated human ownership, with strong autonomous machine discretion inside the broad interval. Speculative AI-mastermind lore is not used as a confirmed explanation of the controller. The moderate nonworking scenario counts industry, logistics, services, administration, maintenance, care and useful creation. AI capacity, ship staffing and industrial output are not a population labor census. The record concerns functioning colonies rather than every wartime collapse or campaign outcome, preserving uncertain household coverage without omitting the familiar corporate automation comparison.''',
(.8,.03,.35),([.15,.98],[-1,.45],[.03,.9]),('Corporate technical capacity does not establish dependable equal support.','Corporate concentration is central with major autonomous-AI alternatives explicit.','Human industrial and caring roles remain; AI capacity is not participation.'),
['Tri-Tachyon specializes in AI and high-power devices and has an industrial colony at Culann.'],['Effective controller identity and household coverage remain uncertain.','Speculative AI-mastermind claims are not treated as established facts.'],'Retain the famous corporate AI economy with speculative controller lore separated.',extra=['src-starsector-tritach-technical'])

add('c0882','stellaris-human-stratified-robot-zero','Stellaris (human Stratified Economy with robotic production)','Stellaris',['game'],'A functioning selected stratified robot-supported human economy','Living human citizens across the selected strata','Robots are not extra humans; code labels such as Civilian jobs do not alone prove particular useful duties or inactivity.',
'''The selected human empire combines robotic production with Stratified Economy living standards. Unlike the Utopian Abundance configuration, its ordinary access is deliberately unequal between strata. The guarantee best guess is weak across citizens because productive capacity does not grant an equal secure floor. This is a modeled zero variant with retained human contribution, not a statement that every version of Stellaris has identical job and living-standard rules.

 Concentrated human elite ownership receives control near zero, qualified by some broader civic agency. Robot equipment does not automatically become an independent AI sovereign. The modest nonworking scenario counts human production, services, administration, maintenance, care and useful creation. Later Civilian-job classifications are not automatically converted into literal activity counts: useful or assigned roles count, passive statistical representation alone does not settle participation. No unemployment or robot ratio is used as a census. The player-configuration flag and broad bounds preserve version uncertainty while keeping the distinct weak-floor institutional choice reviewable.''',
(.8,.05,.3),([.2,.98],[0,.5],[.03,.9]),('Selected unequal strata weaken universal secure access despite robotic output.','Human elite concentration is central despite some wider agency.','Human useful/assigned roles count; code job labels and robot shares are not a census.'),
['Official economic updates alter unemployment/Civilian-job representation and living standards.'],['A functioning human Stratified Economy with robot production is the selected model.','Qualitative unequal access is scored without importing unstable numerical rules.'],'Retain the distinct weak-floor robotic-production configuration with version limits explicit.',branch='Human citizen Stratified Economy and actual robot basic-resource production; qualitative rules only')

add('c0893','suffadv-patentoffice-work-zero','Sufficiently Advanced (Patent Office field agents)','Sufficiently Advanced',['tabletop'],'The functioning Patent Office’s active field-agent work unit','Active human-descended Inspector identities','The fourteen civilizations are not one household economy; off-duty populations, inactive copies and the AI employers are separate.',
'''The Patent Office works across different civilizations in a world of molecular replication and transmutation. Its Inspectors perform real registration, enforcement and arbitration duties under Transcendental AI employers. The retained material unit is that continuing agency cohort, not an invented common economy for fourteen societies. The guarantee best guess allows partial institutional support while keeping employment, missions and uncertain ordinary coverage conditional.

 The Transcendentals’ decisive institutional influence gives strongly negative control weight, qualified by treaty powers and agents’ local discretion. Owning excellent equipment does not mean Inspectors control their employers. The central nonworking scenario is zero for the scoped active field-agent cohort because legal investigation, arbitration and mission work count as useful roles. The broader setting’s abundance is not copied into universal leisure, and an inactive backup is not an additional supported person. This zero variant preserves a concrete AI-backed work institution with direct fabrication provenance while leaving each civilization’s own allocation system separate.''',
(.25,-.95,0),([-.8,.95],[-1,-.4],[0,.8]),('Institutional technical support is plausible but tied to active agency roles.','Transcendental AI employers dominate the office despite treaty and local limits.','Active Inspectors perform real legal/mission work; other civilizations are separate.'),
['The primary sample describes molecular replication/transmutation, working Inspectors and Transcendental AI employers.'],['Only the active field-agent support unit is scored.','No common household constitution is assigned to all fourteen civilizations.'],'Retain the actual fabrication-enabled AI-backed work institution rather than merge different societies.',regime=6,proxy=True,extra=['src-suffadv-patent-primary'])

add('c0894','reignsteel-washington-protectorate-zero','Reign of Steel (the Washington Protectorate)','GURPS Reign of Steel',['tabletop'],'The functioning ostensibly independent Protectorate under covert AI rule','Living human Washington Protectorate residents','Machine manufacturing is not automatically equal human access; dead humans, prison casualties and inactive copies are excluded.',
'''Washington covertly rules a Protectorate that appears independent to its human population. Automated manufacturing exists in the machine-zone setting, but the human share of its output is uncertain. The guarantee best guess is weak because hidden control and vulnerable access prevent assuming a dependable common floor. This zero variant compares continued human roles with machine productive capacity rather than treating an independent national label as proof of human economic freedom.

 Effective covert AI authority gives strongly negative control weight despite outward human institutions. Political appearance does not determine who can command the sustaining systems. The low nonworking scenario counts production, services, administration, maintenance, care and useful creation among living residents. Survival after a robot war is not itself leisure, and the number killed never becomes a nonworking percentage. Broad intervals preserve the unknown household allocation without requiring a complete fictional welfare code. The Protectorate remains distinct from London’s surviving nation, whose machine noninterference is not the same control arrangement.''',
(.8,-.98,.25),([-.4,1],[-1,-.7],[.02,.9]),('Covert domination and uncertain output access imply weak dependable human support.','Washington’s AI has effective authority despite outward independence.','Living residents retain useful roles; war deaths are excluded.'),
['Machine zones have automated manufacturing; Washington covertly rules an ostensibly independent Protectorate.'],['The ordinary human share of machine output is uncertain.','Participation is a living-resident scenario, not a survivor ratio.'],'Retain the covert AI-controlled human polity with its weak-floor uncertainty explicit.',regime=6)

add('c0895','reignsteel-london-human-zero','Reign of Steel (London’s surviving human nation)','GURPS Reign of Steel',['tabletop'],'The functioning human nation under London’s noninterference','Living human residents of the surviving nation','AI noninterference is not automatic AI provisioning; neighboring machine zones and hostile populations have different access.',
'''London leaves a surviving human nation alone within a world of machine-controlled automated production. That is a different relationship from Washington’s hidden government. The guarantee best guess is weak and conditional because being tolerated does not itself provide food, shelter or care. The zero-variant qualification is cautious technological capacity and retained human activity; direct machine-funded universal provision is not claimed.

 Human institutions receive positive control weight for the nation’s own ordinary economic activity. A powerful AI beyond its boundary is not automatically its sustaining sovereign when it chooses noninterference. The modest nonworking scenario counts production, services, administration, repair, care and useful creation. Surviving a machine war is not an employment statistic, and fear or exclusion does not make every person idle. Wide intervals preserve both infrastructure dependence and uncertain local rights. The scope avoids inventing one benevolent AI welfare system from the simple fact that a biological population remains alive.''',
(.65,.35,.25),([-.6,.98],[-.6,.9],[.02,.9]),('Toleration does not establish secure provision; local access remains conditional.','Human economic institutions are central under AI noninterference.','Useful production and care remain; survival is not a nonworking statistic.'),
['London leaves a surviving human nation alone; the surrounding machine zones have automated manufacturing.'],['The nation’s technological substitution and household allocation are uncertain.','Noninterference is not treated as direct AI welfare.'],'Retain the distinct tolerated human economy without assigning control from an external threat.')

add('c0914','logansrun-tv-human-council','Logan’s Run (the television City of Domes)','Logan’s Run (television)',['tv'],'The established television city before the fugitives leave','Living human city residents before the thirty-year termination threshold','The film’s AI ruler and different novel institutions are excluded; terminated residents are not leisure citizens.',
'''The television City of Domes is secretly governed by older humans while enforcing a thirty-year rule on ordinary residents. Its high-capacity enclosed environment is a plausible technical support order, but bodily security is sharply conditional. The guarantee best guess allows a substantial internal floor without calling forced termination a dependable lifetime guarantee. Household coverage is estimated rather than copied wholesale from the film.

 Concentrated human council authority receives control near the elite reference point. The film’s central-machine sovereignty is not imported into this continuity simply because both cities use advanced systems. The high nonworking scenario permits extensive routine substitution while counting assigned security, administration, maintenance, care and useful creation. Short lives and deaths are not converted into a leisure percentage. The television period and controller remain explicit, preventing the original novel, film and series from being merged into one contradictory society or counted again merely for identical visual scenery.''',
(-.15,.03,.7),([-.85,.9],[0,.35],[.1,.98]),('Internal support is plausible but the termination rule sharply limits lifetime security.','Older human council members govern this television continuity.','Substantial substitution may coexist with assigned roles and care; deaths are excluded.'),
['The television city is secretly governed by older human citizens and enforces a thirty-year rule.'],['The household technical floor and participation are low-confidence TV-specific estimates.','Film AI control and novel institutions are not imported.'],'Retain the materially different human-ruled television dome in its own continuity.',regime=1,zero=False,continuity='1977 television series only; film and original novel excluded')

add('c0916','finalspace-galaxyone-sentence-zero','Final Space (Gary’s Galaxy One sentence)','Final Space',['cartoon','tv'],'Gary’s continuing early five-year satellite-repair sentence aboard Galaxy One','The one active living human prisoner Gary','Machine companions are separately disclosed; later Infinity ships and wider adventure crews are different scopes.',
'''Gary serves five years repairing satellites with machine companions aboard Galaxy One. The discovery lead’s Infinity label is corrected to the supported ship and period. Automated bodily support and robotic assistance coexist with an actual imposed human role. The guarantee best guess allows a partial institutional floor, qualified by incarceration and dependence on the ship’s rules. The repair duty is not called useless make-work without evidence.

 Practical ship AI authority receives negative control weight alongside the human legal framework imposing the sentence. Formal human ownership does not erase day-to-day machine discretion, but the ship is not assumed to be an independent worldwide AI government. The central nonworking value is zero for the single active human because recurring satellite repair is work. Alternatives are binary rather than fractions of the five years. Robot count, isolation and time resting do not create additional leisure citizens. This narrow zero variant covers the continuing sentence rather than later crews or ships.''',
(.15,-.55,0),([-.75,.95],[-1,.25],[0,1]),('Institutional life support is partial and conditional on imprisonment/ship rules.','Practical ship AI authority coexists with human sentencing institutions.','One active prisoner performs real repairs centrally; singleton alternatives are binary.'),
['Gary serves five years repairing satellites aboard Galaxy One with machine companions.'],['Galaxy One replaces the discovery lead’s unsupported Infinity label.','Recurring repair is work, not assumed make-work.'],'Retain the actual automated-support/assigned-work unit with ship identity and denominator corrected.',regime=6)

add('c0918','exocolonist-stratos-work-zero','I Was a Teenage Exocolonist (the Vertumna colony)','I Was a Teenage Exocolonist',['game'],'The functioning Stratospheric colony on Vertumna','Living human colonists, including children doing useful roles','Children’s actual work counts; private schooling and play are not automatically jobs and alternate endings are separate.',
'''Colonists and children perform farming, compost work, repair, care, construction and research alongside advanced technology. The material system is therefore an engineered frontier community retaining substantial useful contribution. The guarantee best guess allows a partial shared floor, qualified by survival pressures and local duties. Technical capacity and communal life do not themselves prove that every necessity arrives automatically or that all work is already dispensable.

 Human community institutions receive positive control weight, with leadership and infrastructure dependence inside the interval. A technological colony is not automatically an autonomous AI government. The low nonworking scenario counts the stated productive and caring roles, including work actually done by children. Private learning and play are not assumed useful labor merely because they consume time. Farm output and the protagonist’s schedule are not a population employment census. This zero variant selects the functioning colony rather than combining every possible ending or assigning one universal rights system to the whole planet.''',
(.2,.6,.15),([-.7,.95],[0,1],[.02,.8]),('Shared frontier support is plausible but survival pressure and duties condition it.','Human communal institutions retain agency with practical concentration possible.','Actual child/adult productive roles and care count; private study/play are distinct.'),
['Colonists and children perform farming, compost work, repair, care, construction and research alongside technology.'],['The shared material floor and automation depth are cautious estimates.','The ordinary functioning colony is separate from alternate endings.'],'Retain the recognizable technological working commune with useful child and care activity explicit.')

add('c0920','suffadv-tao-historical-communities','Sufficiently Advanced (the Tao of History’s maintained societies)','Sufficiently Advanced',['tabletop'],'The functioning first-edition historical recreation communities','Living human and active human-derived Tao citizens','Mostly nonsentient robot slaves are equipment, not extra persons; real generations are distinct from temporary visitor avatars.',
'''Tao citizens inhabit historical recreations with real generations, variable local rule and robot labor where appropriate. They are residents rather than merely temporary avatars in an attraction. The guarantee best guess allows a strong underlying technical floor, qualified by local restrictions and staged conflict. A historical appearance does not prove that residents depend on wholly preindustrial production, while recreating a society does not itself guarantee equal access everywhere.

 Human resident and organizing institutions receive positive control weight. Mostly nonsentient robot labor is equipment under that arrangement, not automatically an AI sovereign. The low-to-moderate nonworking scenario counts care, administration, maintenance and performance that provides entertainment to others. Private historical play is not automatically a job, and voluntary useful performance is not automatically leisure. Only active persons enter the proxy population. The point preserves the Tao’s distinct maintained-historical material model rather than merging it with Stardweller basics or the Patent Office’s employed field agents.''',
(-.55,.55,.3),([-.95,.8],[0,1],[.03,.9]),('Underlying robot support allows a strong floor, with variable local restrictions.','Human resident/organizing agency is central; mostly nonsentient robots are equipment.','Useful performance and care count; private play and visitor avatars are distinct.'),
['Historical recreations have real generations, mostly nonsentient robot labor, variable rule and controlled staged conflict.','Citizens provide entertainment rather than only visiting as avatars.'],['Underlying material coverage is a low-confidence interpretation.','Useful performance and private historical play have different work status.'],'Retain the distinct maintained historical resident society with real useful activity visible.',regime=2,zero=False,proxy=True,continuity='First-edition Tao of History model in the checked review and primary setting passages')

# Purism changes body/augmentation choices, not a third compiler-access class.
r=deepcopy(D['societies']['nova-praxis-citizen-compiler-floor'])
r['related_candidate_ids']=sorted(set(r.get('related_candidate_ids',[])+['c0870']))
r['editorial_assumptions'].append('Purist augmentation restrictions do not establish a third material-access class separate from the existing citizen/Apostate scopes.')
r['review']['date']=DATE
changes.append(change(D,'societies',r))
d=deepcopy(D['decisions']['c0870']);d.update(status='duplicate',society_id=r['id'],duplicate_of=r['id'],current_policy_review=True,reassessed_on=DATE,reason='Purist bodily-augmentation restrictions do not establish another compiler/allocation regime; citizen and Apostate access are already retained separately.',analysis='The same primary preview gives citizens a default resource floor and compilers, excludes Apostates from Coalition resources and separately describes Purist body restrictions. Augmentation preference is not counted as a third productive constitution.',follow_up='Linked material-model overlap; existing citizen and Apostate coverage remains authoritative.');changes.append(change(D,'decisions',d))
for r in records:changes.extend([change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))])
assert len(records)==13,len(records)
write_revision(30,changes,'Thirteen further multimedia models retained, finishing the present multimedia follow-up tier. Lancer and Starsector institutions remain distinct; the Patent Office is a real AI-backed work unit, television Logan’s Run is human-ruled, Gary’s ship is corrected to Galaxy One and the Tao has real resident generations. Nova Praxis Purists link to existing material-access classes rather than adding a duplicate point.')
